from openpyxl import load_workbook
from pathlib import Path
for p in sorted(Path('review/downloads').glob('*.xlsx')):
 print('\\nDOCUMENT',p.name)
 w=load_workbook(p,data_only=True)
 for s in w:
  print('SHEET',s.title)
  for row in s:
   vals=['%s=%s'%(c.coordinate,c.value) for c in row if c.value is not None]
   if vals: print(' | '.join(vals))
PY"

